mel: added both. See snippet below (Python async streaming with retry/backoff and pagination):

```python
# async streaming generator + simple backoff
import asyncio
from redwood import AsyncClient, APIError

async def stream_with_retry(prompt):
    client = AsyncClient()
    backoff = 0.5
    for attempt in range(4):
        try:
            async for chunk in client.chat.stream(prompt):
                yield chunk
            return
        except APIError as e:
            if e.status >= 500:
                await asyncio.sleep(backoff)
                backoff *= 2
            else:
                raise
```

leo: looks good. minor nit: use named constant for max attempts. also prefer `asynccontextmanager` for client.

jamie: for TS we should show readable stream + manual reconnect on network error. I can add a snippet.

jamie: 
```ts
// TypeScript: ReadableStream + retry (fetch-like API)
import { RedwoodClient } from "@redwood/inference";

const client = new RedwoodClient();

async function streamChatWithRetry(prompt: string) {
  let backoff = 500;
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      const res = await client.chat.stream({ prompt });
      for await (const chunk of res) {
        console.log(chunk);
      }
      return;
    } catch (err) {
      if (err.status && err.status >= 500) {
        await new Promise(r => setTimeout(r, backoff));
        backoff *= 2;
      } else throw err;
    }
  }
}
```

sudha: can TS snippet use `for await (const chunk of res)`? Some folks use async iterators, yes.

mel: Go snippet needs to show cursor pagination + streaming combiner. Here's my draft:

```go
// Go: cursor pagination + simple streaming reader
package docs

import (
  "context"
  "time"
  "github.com/redwood/inference-go"
)

func FetchAllEmbeddings(ctx context.Context, client *inference.Client, q string) ([]float64, error) {
  var all []float64
  cursor := ""
  for {
    resp, err := client.Embeddings(ctx, &inference.EmbeddingsRequest{Query: q, Cursor: cursor})
    if err != nil { return nil, err }
    all = append(all, resp.Embeddings...)
    if resp.NextCursor == "" { break }
    cursor = resp.NextCursor
    time.Sleep(100 * time.Millisecond)
  }
  return all, nil
}
```

